struct JSIRuntime {
    JSIMallocFunctions mf;
    JSIMallocState malloc_state;
    const char *rt_info;

    int atom_hash_size; /* power of two */
    int atom_count;
    int atom_size;
    int atom_count_resize; /* resize hash table at this count */
    uint32_t *atom_hash;
    JSAtomStruct **atom_array;
    int atom_free_index; /* 0 = none */

    int class_count;    /* size of class_array */
    JSIClass *class_array;

    struct list_head context_list; /* list of JSIContext.link */
    /* list of JSIGCObjectHeader.link. List of allocated GC objects (used
       by the garbage collector) */
    struct list_head gc_obj_list;
    /* list of JSIGCObjectHeader.link. Used during JSI_FreeValueRT() */
    struct list_head gc_zero_ref_count_list;
    struct list_head tmp_obj_list; /* used during GC */
    JSGCPhaseEnum gc_phase : 8;
    size_t malloc_gc_threshold;
    struct list_head weakref_list; /* list of JSWeakRefHeader.link */
#ifdef DUMP_LEAKS
    struct list_head string_list; /* list of JSIString.link */
#endif
    /* stack limitation */
    uintptr_t stack_size; /* in bytes, 0 if no limit */
    uintptr_t stack_top;
    uintptr_t stack_limit; /* lower stack limit */

    JSIValue current_exception;
    /* true if the current exception cannot be catched */
    BOOL current_exception_is_uncatchable : 8;
    /* true if inside an out of memory error, to avoid recursing */
    BOOL in_out_of_memory : 8;

    struct JSIStackFrame *current_stack_frame;

    JSIInterruptHandler *interrupt_handler;
    void *interrupt_opaque;

    JSIHostPromiseRejectionTracker *host_promise_rejection_tracker;
    void *host_promise_rejection_tracker_opaque;

    JSIHostPromiseRejectionTracker *host_unhandled_promise_rejection_tracker;
    void *host_unhandled_promise_rejection_tracker_opaque;

    struct list_head job_list; /* list of JSJobEntry.link */

    JSIModuleNormalizeFunc *module_normalize_func;
    BOOL module_loader_has_attr;
    union {
        JSIModuleLoaderFunc *module_loader_func;
        JSIModuleLoaderFunc2 *module_loader_func2;
    } u;
    JSIModuleCheckSupportedImportAttributes *module_check_attrs;
    void *module_loader_opaque;
    /* timestamp for internal use in module evaluation */
    int64_t module_async_evaluation_next_timestamp;

    BOOL can_block : 8; /* TRUE if Atomics.wait can block */
    /* used to allocate, free and clone SharedArrayBuffers */
    JSISharedArrayBufferFunctions sab_funcs;
    /* see JSI_SetStripInfo() */
    uint8_t strip_flags;
    
    /* Shape hash table */
    int shape_hash_bits;
    int shape_hash_size;
    int shape_hash_count; /* number of hashed shapes */
    JSIShape **shape_hash;
    void *user_opaque;
};

struct JSIClass {
    uint32_t class_id; /* 0 means free entry */
    JSAtom class_name;
    JSIClassFinalizer *finalizer;
    JSIClassGCMark *gc_mark;
    JSIClassCall *call;
    /* pointers for exotic behavior, can be NULL if none are present */
    const JSIClassExoticMethods *exotic;
};

#define JSI_MODE_STRICT (1 << 0)
#define JSI_MODE_ASYNC  (1 << 2) /* async function */
#define JSI_MODE_BACKTRACE_BARRIER (1 << 3) /* stop backtrace before this frame */

typedef struct JSIStackFrame {
    struct JSIStackFrame *prev_frame; /* NULL if first stack frame */
    JSIValue cur_func; /* current function, JSI_UNDEFINED if the frame is detached */
    JSIValue *arg_buf; /* arguments */
    JSIValue *var_buf; /* variables */
    struct list_head var_ref_list; /* list of JSVarRef.var_ref_link */
    const uint8_t *cur_pc; /* only used in bytecode functions : PC of the
                        instruction after the call */
    int arg_count;
    int jsi_mode; /* not supported for C functions */
    /* only used in generators. Current stack pointer value. NULL if
       the function is running. */
    JSIValue *cur_sp;
} JSIStackFrame;

typedef enum {
    JSI_GC_OBJ_TYPE_JSI_OBJECT,
    JSI_GC_OBJ_TYPE_FUNCTION_BYTECODE,
    JSI_GC_OBJ_TYPE_SHAPE,
    JSI_GC_OBJ_TYPE_VAR_REF,
    JSI_GC_OBJ_TYPE_ASYNC_FUNCTION,
    JSI_GC_OBJ_TYPE_JSI_CONTEXT,
    JSI_GC_OBJ_TYPE_MODULE,
} JSGCObjectTypeEnum;

/* header for GC objects. GC objects are C data structures with a
   reference count that can reference other GC objects. JS Objects are
   a particular type of GC object. */
struct JSIGCObjectHeader {
    int ref_count; /* must come first, 32-bit */
    JSGCObjectTypeEnum gc_obj_type : 4;
    uint8_t mark : 4; /* used by the GC */
    uint8_t dummy1; /* not used by the GC */
    uint16_t dummy2; /* not used by the GC */
    struct list_head link;
};



typedef struct JSVarRef {
    union {
        JSIGCObjectHeader header; /* must come first */
        struct {
            int __gc_ref_count; /* corresponds to header.ref_count */
            uint8_t __gc_mark; /* corresponds to header.mark/gc_obj_type */
            uint8_t is_detached;
        };
    };
    JSIValue *pvalue; /* pointer to the value, either on the stack or
                        to 'value' */
    union {
        JSIValue value; /* used when is_detached = TRUE */
        struct {
            struct list_head var_ref_link; /* JSIStackFrame.var_ref_list list */
            struct JSAsyncFunctionState *async_func; /* != NULL if async stack frame */
        }; /* used when is_detached = FALSE */
    };
} JSVarRef;

/* bigint */

#if JSI_LIMB_BITS == 32

typedef int32_t jsi_slimb_t;
typedef uint32_t jsi_limb_t;
typedef int64_t jsi_sdlimb_t;
typedef uint64_t jsi_dlimb_t;

#define JSI_LIMB_DIGITS 9

#else

typedef __int128 int128_t;
typedef unsigned __int128 uint128_t;
typedef int64_t jsi_slimb_t;
typedef uint64_t jsi_limb_t;
typedef int128_t jsi_sdlimb_t;
typedef uint128_t jsi_dlimb_t;

#define JSI_LIMB_DIGITS 19

#endif

typedef struct JSBigInt {
    JSIRefCountHeader header; /* must come first, 32-bit */
    uint32_t len; /* number of limbs, >= 1 */
    jsi_limb_t tab[]; /* two's complement representation, always
                        normalized so that 'len' is the minimum
                        possible length >= 1 */
} JSBigInt;

/* this bigint structure can hold a 64 bit integer */
typedef struct {
    jsi_limb_t big_int_buf[sizeof(JSBigInt) / sizeof(jsi_limb_t)]; /* for JSBigInt */
    /* must come just after */
    jsi_limb_t tab[(64 + JSI_LIMB_BITS - 1) / JSI_LIMB_BITS];
} JSBigIntBuf;
    
typedef enum {
    JSI_AUTOINIT_ID_PROTOTYPE,
    JSI_AUTOINIT_ID_MODULE_NS,
    JSI_AUTOINIT_ID_PROP,
} JSAutoInitIDEnum;

/* must be large enough to have a negligible runtime cost and small
   enough to call the interrupt callback often. */
#define JSI_INTERRUPT_COUNTER_INIT 10000

struct JSIContext {
    JSIGCObjectHeader header; /* must come first */
    JSIRuntime *rt;
    struct list_head link;

    uint16_t binary_object_count;
    int binary_object_size;

    JSIShape *array_shape;   /* initial shape for Array objects */

    JSIValue *class_proto;
    JSIValue function_proto;
    JSIValue function_ctor;
    JSIValue array_ctor;
    // JSIValue regexp_ctor;
    // JSIValue promise_ctor;
    JSIValue native_error_proto[JSI_NATIVE_ERROR_COUNT];
    JSIValue iterator_proto;
    JSIValue async_iterator_proto;
    JSIValue array_proto_values;
    JSIValue throw_type_error;
    JSIValue eval_obj;

    JSIValue global_obj; /* global object */
    JSIValue global_var_obj; /* contains the global let/const definitions */

    uint64_t random_state;

    /* when the counter reaches zero, JSRutime.interrupt_handler is called */
    int interrupt_counter;

    struct list_head loaded_modules; /* list of JSIModuleDef.link */

    /* if NULL, RegExp compilation is not supported */
    // JSIValue (*compile_regexp)(JSIContext *ctx, JSIValueConst pattern,
    //                           JSIValueConst flags);
    /* if NULL, eval is not supported */
    JSIValue (*eval_internal)(JSIContext *ctx, JSIValueConst this_obj,
                             const char *input, size_t input_len,
                             const char *filename, int flags, int scope_idx);
    void *user_opaque;
};

