static JSIValue make_obj_error(JSIContext *ctx,
                              JSIValue obj,
                              int err)
{
    JSIValue arr;
    if (JSI_IsException(obj))
        return obj;
    arr = JSI_NewArray(ctx);
    if (JSI_IsException(arr))
        return JSI_EXCEPTION;
    JSI_DefinePropertyValueUint32(ctx, arr, 0, obj,
                                 JSI_PROP_C_W_E);
    JSI_DefinePropertyValueUint32(ctx, arr, 1, JSI_NewInt32(ctx, err),
                                 JSI_PROP_C_W_E);
    return arr;
}

static JSIValue make_string_error(JSIContext *ctx,
                                 const char *buf,
                                 int err)
{
    return make_obj_error(ctx, JSI_NewString(ctx, buf), err);
}

