/* default memory allocation functions with memory limitation */
static size_t jsi_def_malloc_usable_size(const void *ptr)
{
#if defined(__APPLE__)
    return malloc_size(ptr);
#elif defined(_WIN32)
    return _msize((void *)ptr);
#elif defined(EMSCRIPTEN)
    return 0;
#elif defined(__linux__) || defined(__GLIBC__)
    return malloc_usable_size((void *)ptr);
#else
    /* change this to `return 0;` if compilation fails */
    return malloc_usable_size((void *)ptr);
#endif
}

static void *jsi_def_malloc(JSIMallocState *s, size_t size)
{
    void *ptr;

    /* Do not allocate zero bytes: behavior is platform dependent */
    assert(size != 0);

    if (unlikely(s->malloc_size + size > s->malloc_limit))
        return NULL;

    ptr = malloc(size);
    if (!ptr)
        return NULL;

    s->malloc_count++;
    s->malloc_size += jsi_def_malloc_usable_size(ptr) + MALLOC_OVERHEAD;
    return ptr;
}

static void jsi_def_free(JSIMallocState *s, void *ptr)
{
    if (!ptr)
        return;

    s->malloc_count--;
    s->malloc_size -= jsi_def_malloc_usable_size(ptr) + MALLOC_OVERHEAD;
    free(ptr);
}

static void *jsi_def_realloc(JSIMallocState *s, void *ptr, size_t size)
{
    size_t old_size;

    if (!ptr) {
        if (size == 0)
            return NULL;
        return jsi_def_malloc(s, size);
    }
    old_size = jsi_def_malloc_usable_size(ptr);
    if (size == 0) {
        s->malloc_count--;
        s->malloc_size -= old_size + MALLOC_OVERHEAD;
        free(ptr);
        return NULL;
    }
    if (s->malloc_size + size - old_size > s->malloc_limit)
        return NULL;

    ptr = realloc(ptr, size);
    if (!ptr)
        return NULL;

    s->malloc_size += jsi_def_malloc_usable_size(ptr) - old_size;
    return ptr;
}

static const JSIMallocFunctions def_malloc_funcs = {
    jsi_def_malloc,
    jsi_def_free,
    jsi_def_realloc,
    jsi_def_malloc_usable_size,
};

JSIRuntime *JSI_NewRuntime(void)
{
    return JSI_NewRuntime2(&def_malloc_funcs, NULL);
}

