/* return an empty string if not an object */
static JSIValue jsi_object___getClass(JSIContext *ctx, JSIValueConst this_val,
                                    int argc, JSIValueConst *argv)
{
    JSAtom atom;
    JSObject *p;
    uint32_t tag;
    int class_id;

    tag = JSI_VALUE_GET_NORM_TAG(argv[0]);
    if (tag == JSI_TAG_OBJECT) {
        p = JSI_VALUE_GET_OBJ(argv[0]);
        class_id = p->class_id;
        atom = ctx->rt->class_array[class_id].class_name;
    } else {
        atom = JSI_ATOM_empty_string;
    }
    return JSI_AtomToString(ctx, atom);
}

