static JSIValue JSI_SpeciesConstructor(JSIContext *ctx, JSIValueConst obj,
                                     JSIValueConst defaultConstructor)
{
    JSIValue ctor, species;

    if (!JSI_IsObject(obj))
        return JSI_ThrowTypeErrorNotAnObject(ctx);
    ctor = JSI_GetProperty(ctx, obj, JSI_ATOM_constructor);
    if (JSI_IsException(ctor))
        return ctor;
    if (JSI_IsUndefined(ctor))
        return JSI_DupValue(ctx, defaultConstructor);
    if (!JSI_IsObject(ctor)) {
        JSI_FreeValue(ctx, ctor);
        return JSI_ThrowTypeErrorNotAnObject(ctx);
    }
    species = JSI_GetProperty(ctx, ctor, JSI_ATOM_Symbol_species);
    JSI_FreeValue(ctx, ctor);
    if (JSI_IsException(species))
        return species;
    if (JSI_IsUndefined(species) || JSI_IsNull(species))
        return JSI_DupValue(ctx, defaultConstructor);
    if (!JSI_IsConstructor(ctx, species)) {
        JSI_FreeValue(ctx, species);
        return JSI_ThrowTypeError(ctx, "not a constructor");
    }
    return species;
}

