static JSIValue jsi_object_get___proto__(JSIContext *ctx, JSIValueConst this_val)
{
    JSIValue val, ret;

    val = JSI_ToObject(ctx, this_val);
    if (JSI_IsException(val))
        return val;
    ret = JSI_GetPrototype(ctx, val);
    JSI_FreeValue(ctx, val);
    return ret;
}

static JSIValue jsi_object_set___proto__(JSIContext *ctx, JSIValueConst this_val,
                                       JSIValueConst proto)
{
    if (JSI_IsUndefined(this_val) || JSI_IsNull(this_val))
        return JSI_ThrowTypeErrorNotAnObject(ctx);
    if (!JSI_IsObject(proto) && !JSI_IsNull(proto))
        return JSI_UNDEFINED;
    if (JSI_SetPrototypeInternal(ctx, this_val, proto, TRUE) < 0)
        return JSI_EXCEPTION;
    else
        return JSI_UNDEFINED;
}

static JSIValue jsi_object_isPrototypeOf(JSIContext *ctx, JSIValueConst this_val,
                                       int argc, JSIValueConst *argv)
{
    JSIValue obj, v1;
    JSIValueConst v;
    int res;

    v = argv[0];
    if (!JSI_IsObject(v))
        return JSI_FALSE;
    obj = JSI_ToObject(ctx, this_val);
    if (JSI_IsException(obj))
        return JSI_EXCEPTION;
    v1 = JSI_DupValue(ctx, v);
    for(;;) {
        v1 = JSI_GetPrototypeFree(ctx, v1);
        if (JSI_IsException(v1))
            goto exception;
        if (JSI_IsNull(v1)) {
            res = FALSE;
            break;
        }
        if (JSI_VALUE_GET_OBJ(obj) == JSI_VALUE_GET_OBJ(v1)) {
            res = TRUE;
            break;
        }
        /* avoid infinite loop (possible with proxies) */
        if (jsi_poll_interrupts(ctx))
            goto exception;
    }
    JSI_FreeValue(ctx, v1);
    JSI_FreeValue(ctx, obj);
    return JSI_NewBool(ctx, res);

exception:
    JSI_FreeValue(ctx, v1);
    JSI_FreeValue(ctx, obj);
    return JSI_EXCEPTION;
}

static JSIValue jsi_object_propertyIsEnumerable(JSIContext *ctx, JSIValueConst this_val,
                                              int argc, JSIValueConst *argv)
{
    JSIValue obj = JSI_UNDEFINED, res = JSI_EXCEPTION;
    JSAtom prop;
    JSIPropertyDescriptor desc;
    int has_prop;

    prop = JSI_ValueToAtom(ctx, argv[0]);
    if (unlikely(prop == JSI_ATOM_NULL))
        goto exception;
    obj = JSI_ToObject(ctx, this_val);
    if (JSI_IsException(obj))
        goto exception;

    has_prop = JSI_GetOwnPropertyInternal(ctx, &desc, JSI_VALUE_GET_OBJ(obj), prop);
    if (has_prop < 0)
        goto exception;
    if (has_prop) {
        res = JSI_NewBool(ctx, desc.flags & JSI_PROP_ENUMERABLE);
        jsi_free_desc(ctx, &desc);
    } else {
        res = JSI_FALSE;
    }

exception:
    JSI_FreeAtom(ctx, prop);
    JSI_FreeValue(ctx, obj);
    return res;
}

static JSIValue jsi_object___lookupGetter__(JSIContext *ctx, JSIValueConst this_val,
                                          int argc, JSIValueConst *argv, int setter)
{
    JSIValue obj, res = JSI_EXCEPTION;
    JSAtom prop = JSI_ATOM_NULL;
    JSIPropertyDescriptor desc;
    int has_prop;

    obj = JSI_ToObject(ctx, this_val);
    if (JSI_IsException(obj))
        goto exception;
    prop = JSI_ValueToAtom(ctx, argv[0]);
    if (unlikely(prop == JSI_ATOM_NULL))
        goto exception;

    for (;;) {
        has_prop = JSI_GetOwnPropertyInternal(ctx, &desc, JSI_VALUE_GET_OBJ(obj), prop);
        if (has_prop < 0)
            goto exception;
        if (has_prop) {
            if (desc.flags & JSI_PROP_GETSET)
                res = JSI_DupValue(ctx, setter ? desc.setter : desc.getter);
            else
                res = JSI_UNDEFINED;
            jsi_free_desc(ctx, &desc);
            break;
        }
        obj = JSI_GetPrototypeFree(ctx, obj);
        if (JSI_IsException(obj))
            goto exception;
        if (JSI_IsNull(obj)) {
            res = JSI_UNDEFINED;
            break;
        }
        /* avoid infinite loop (possible with proxies) */
        if (jsi_poll_interrupts(ctx))
            goto exception;
    }

exception:
    JSI_FreeAtom(ctx, prop);
    JSI_FreeValue(ctx, obj);
    return res;
}

