static int jsi_get_radix(JSIContext *ctx, JSIValueConst val)
{
    int radix;
    if (JSI_ToInt32Sat(ctx, &radix, val))
        return -1;
    if (radix < 2 || radix > 36) {
        JSI_ThrowRangeError(ctx, "radix must be between 2 and 36");
        return -1;
    }
    return radix;
}
static int i64toa_radix(char *buf, int64_t n, int base) {
    static const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";
    char tmp[70];
    int i = 0, neg = 0;
    uint64_t u = n < 0 ? -(uint64_t)n : (uint64_t)n;
    neg = (n < 0);
    do { tmp[i++] = digits[u % base]; u /= base; } while (u);
    int j = 0;
    if (neg) buf[j++] = '-';
    while (i) buf[j++] = tmp[--i];
    buf[j] = 0;
    return j;
}
static JSIValue jsi_number_toString(JSIContext *ctx, JSIValueConst this_val,
                                  int argc, JSIValueConst *argv, int magic)
{
    JSIValue val;
    int base, flags;
    // double d;

    val = jsi_thisNumberValue(ctx, this_val);
    if (JSI_IsException(val))
        return val;
    if (magic || JSI_IsUndefined(argv[0])) {
        base = 10;
    } else {
        base = jsi_get_radix(ctx, argv[0]);
        if (base < 0)
            goto fail;
    }
    if (JSI_VALUE_GET_TAG(val) == JSI_TAG_INT) {
        char buf1[70];
        int len;
        int64_t n = JSI_VALUE_GET_INT(val);
        if (base == 10) {
            len = snprintf(buf1, sizeof buf1, "%lld", (long long)n);
        } else {
            /* i64toa_radix должен быть доступен или реализуйте вручную */
            len = (int)i64toa_radix(buf1, n, base);
        }
        return jsi_new_string8_len(ctx, buf1, len);
} 
fail:
    JSI_FreeValue(ctx, val);
    return JSI_EXCEPTION;
}



