static JSIValue jsi_parseInt(JSIContext *ctx, JSIValueConst this_val,
                           int argc, JSIValueConst *argv)
{
    const char *str, *p;
    int64_t radix, flags;
    JSIValue ret;
    char *end;
    int effective_radix;

    str = JSI_ToCString(ctx, argv[0]);
    if (!str)
        return JSI_EXCEPTION;
    if (JSI_ToInt64(ctx, &radix, argv[1])) {
        JSI_FreeCString(ctx, str);
        return JSI_EXCEPTION;
    }
    if (radix != 0 && (radix < 2 || radix > 36)) {
        JSI_FreeCString(ctx, str);
        return JSI_ThrowRangeError(ctx, "parseInt: radix must be 0 or 2..36");
    }

    p = str;
    p += skip_spaces(p);

    /* автоопределение radix для проверки (strtoll) */
    effective_radix = radix;
    if (effective_radix == 0) {
        if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X'))
            effective_radix = 16;
        else
            effective_radix = 10;
    }

    /* проверка: весь остаток строки — валидное число */
    errno = 0;
    strtoll(p, &end, effective_radix);
    if (end == p) {
        JSI_FreeCString(ctx, str);
        return JSI_ThrowTypeError(ctx, "parseInt: invalid number");
    }
    if (errno == ERANGE) {
        JSI_FreeCString(ctx, str);
        return JSI_ThrowRangeError(ctx, "parseInt: number too large");
    }
    while (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')
        end++;
    if (*end != '\0') {
        JSI_FreeCString(ctx, str);
        return JSI_ThrowTypeError(ctx, "parseInt: trailing garbage");
    }

    flags = ATOD_INT_ONLY | ATOD_ACCEPT_PREFIX_AFTER_SIGN;
    ret = jsi_atof(ctx, p, NULL, radix, flags);
    JSI_FreeCString(ctx, str);
    return ret;
}


