/* String */

static int jsi_string_get_own_property(JSIContext *ctx,
                                      JSIPropertyDescriptor *desc,
                                      JSIValueConst obj, JSAtom prop)
{
    JSObject *p;
    JSIString *p1;
    uint32_t idx, ch;

    /* This is a class exotic method: obj class_id is JSI_CLASS_STRING */
    if (__JSI_AtomIsTaggedInt(prop)) {
        p = JSI_VALUE_GET_OBJ(obj);
        if (JSI_VALUE_GET_TAG(p->u.object_data) == JSI_TAG_STRING) {
            p1 = JSI_VALUE_GET_STRING(p->u.object_data);
            idx = __JSI_AtomToUInt32(prop);
            if (idx < p1->len) {
                if (desc) {
                    ch = string_get(p1, idx);
                    desc->flags = JSI_PROP_ENUMERABLE;
                    desc->value = jsi_new_string_char(ctx, ch);
                    desc->getter = JSI_UNDEFINED;
                    desc->setter = JSI_UNDEFINED;
                }
                return TRUE;
            }
        }
    }
    return FALSE;
}

static int jsi_string_define_own_property(JSIContext *ctx,
                                         JSIValueConst this_obj,
                                         JSAtom prop, JSIValueConst val,
                                         JSIValueConst getter,
                                         JSIValueConst setter, int flags)
{
    uint32_t idx;
    JSObject *p;
    JSIString *p1, *p2;

    if (__JSI_AtomIsTaggedInt(prop)) {
        idx = __JSI_AtomToUInt32(prop);
        p = JSI_VALUE_GET_OBJ(this_obj);
        if (JSI_VALUE_GET_TAG(p->u.object_data) != JSI_TAG_STRING)
            goto def;
        p1 = JSI_VALUE_GET_STRING(p->u.object_data);
        if (idx >= p1->len)
            goto def;
        if (!check_define_prop_flags(JSI_PROP_ENUMERABLE, flags))
            goto fail;
        /* check that the same value is configured */
        if (flags & JSI_PROP_HAS_VALUE) {
            if (JSI_VALUE_GET_TAG(val) != JSI_TAG_STRING)
                goto fail;
            p2 = JSI_VALUE_GET_STRING(val);
            if (p2->len != 1)
                goto fail;
            if (string_get(p1, idx) != string_get(p2, 0)) {
            fail:
                return JSI_ThrowTypeErrorOrFalse(ctx, flags, "property is not configurable");
            }
        }
        return TRUE;
    } else {
    def:
        return JSI_DefineProperty(ctx, this_obj, prop, val, getter, setter,
                                 flags | JSI_PROP_NO_EXOTIC);
    }
}

static int jsi_string_delete_property(JSIContext *ctx,
                                     JSIValueConst obj, JSAtom prop)
{
    uint32_t idx;

    if (__JSI_AtomIsTaggedInt(prop)) {
        idx = __JSI_AtomToUInt32(prop);
        if (idx < jsi_string_obj_get_length(ctx, obj)) {
            return FALSE;
        }
    }
    return TRUE;
}

static const JSIClassExoticMethods jsi_string_exotic_methods = {
    .get_own_property = jsi_string_get_own_property,
    .define_own_property = jsi_string_define_own_property,
    .delete_property = jsi_string_delete_property,
};

static JSIValue jsi_string_constructor(JSIContext *ctx, JSIValueConst new_target,
                                     int argc, JSIValueConst *argv)
{
    JSIValue val, obj;
    if (argc == 0) {
        val = JSI_AtomToString(ctx, JSI_ATOM_empty_string);
    } else {
        if (JSI_IsUndefined(new_target) && JSI_IsSymbol(argv[0])) {
            JSAtomStruct *p = JSI_VALUE_GET_PTR(argv[0]);
            val = JSI_ConcatString3(ctx, "Symbol(", JSI_AtomToString(ctx, jsi_get_atom_index(ctx->rt, p)), ")");
        } else {
            val = JSI_ToString(ctx, argv[0]);
        }
        if (JSI_IsException(val))
            return val;
    }
    if (!JSI_IsUndefined(new_target)) {
        JSIString *p1 = JSI_VALUE_GET_STRING(val);

        obj = jsi_create_from_ctor(ctx, new_target, JSI_CLASS_STRING);
        if (JSI_IsException(obj)) {
            JSI_FreeValue(ctx, val);
        } else {
            JSI_SetObjectData(ctx, obj, val);
            JSI_DefinePropertyValue(ctx, obj, JSI_ATOM_length, JSI_NewInt32(ctx, p1->len), 0);
        }
        return obj;
    } else {
        return val;
    }
}

static JSIValue jsi_thisStringValue(JSIContext *ctx, JSIValueConst this_val)
{
    if (JSI_VALUE_GET_TAG(this_val) == JSI_TAG_STRING ||
        JSI_VALUE_GET_TAG(this_val) == JSI_TAG_STRING_ROPE)
        return JSI_DupValue(ctx, this_val);

    if (JSI_VALUE_GET_TAG(this_val) == JSI_TAG_OBJECT) {
        JSObject *p = JSI_VALUE_GET_OBJ(this_val);
        if (p->class_id == JSI_CLASS_STRING) {
            if (JSI_VALUE_GET_TAG(p->u.object_data) == JSI_TAG_STRING)
                return JSI_DupValue(ctx, p->u.object_data);
        }
    }
    return JSI_ThrowTypeError(ctx, "not a string");
}

static JSIValue jsi_string_fromCharCode(JSIContext *ctx, JSIValueConst this_val,
                                      int argc, JSIValueConst *argv)
{
    int i;
    StringBuffer b_s, *b = &b_s;

    string_buffer_init(ctx, b, argc);

    for(i = 0; i < argc; i++) {
        int32_t c;
        if (JSI_ToInt32(ctx, &c, argv[i]) || string_buffer_putc16(b, c & 0xffff)) {
            string_buffer_free(b);
            return JSI_EXCEPTION;
        }
    }
    return string_buffer_end(b);
}

static JSIValue jsi_string_fromCodePoint(JSIContext *ctx, JSIValueConst this_val,
                                       int argc, JSIValueConst *argv)
{
    int64_t d;
    int i, c;
    StringBuffer b_s, *b = &b_s;

    /* XXX: could pre-compute string length if all arguments are JSI_TAG_INT */

    if (string_buffer_init(ctx, b, argc))
        goto fail;
    for(i = 0; i < argc; i++) {
        if (JSI_VALUE_GET_TAG(argv[i]) == JSI_TAG_INT) {
            c = JSI_VALUE_GET_INT(argv[i]);
            if (c < 0 || c > 0x10ffff)
                goto range_error;
        } else {
            if (JSI_ToInt64(ctx, &d, argv[i]))
                goto fail;
        }
        if (string_buffer_putc(b, c))
            goto fail;
    }
    return string_buffer_end(b);

 range_error:
    JSI_ThrowRangeError(ctx, "invalid code point");
 fail:
    string_buffer_free(b);
    return JSI_EXCEPTION;
}

static JSIValue jsi_string_raw(JSIContext *ctx, JSIValueConst this_val,
                             int argc, JSIValueConst *argv)
{
    // raw(temp,...a)
    JSIValue cooked, val, raw;
    StringBuffer b_s, *b = &b_s;
    int64_t i, n;

    string_buffer_init(ctx, b, 0);
    raw = JSI_UNDEFINED;
    cooked = JSI_ToObject(ctx, argv[0]);
    if (JSI_IsException(cooked))
        goto exception;
    raw = JSI_ToObjectFree(ctx, JSI_GetProperty(ctx, cooked, JSI_ATOM_raw));
    if (JSI_IsException(raw))
        goto exception;
    if (jsi_get_length64(ctx, &n, raw) < 0)
        goto exception;

    for (i = 0; i < n; i++) {
        val = JSI_ToStringFree(ctx, JSI_GetPropertyInt64(ctx, raw, i));
        if (JSI_IsException(val))
            goto exception;
        string_buffer_concat_value_free(b, val);
        if (i < n - 1 && i + 1 < argc) {
            if (string_buffer_concat_value(b, argv[i + 1]))
                goto exception;
        }
    }
    JSI_FreeValue(ctx, cooked);
    JSI_FreeValue(ctx, raw);
    return string_buffer_end(b);

exception:
    JSI_FreeValue(ctx, cooked);
    JSI_FreeValue(ctx, raw);
    string_buffer_free(b);
    return JSI_EXCEPTION;
}

/* only used in test262 */
JSIValue jsi_string_codePointRange(JSIContext *ctx, JSIValueConst this_val,
                                 int argc, JSIValueConst *argv)
{
    uint32_t start, end, i, n;
    StringBuffer b_s, *b = &b_s;

    if (JSI_ToUint32(ctx, &start, argv[0]) ||
        JSI_ToUint32(ctx, &end, argv[1]))
        return JSI_EXCEPTION;
    end = min_uint32(end, 0x10ffff + 1);

    if (start > end) {
        start = end;
    }
    n = end - start;
    if (end > 0x10000) {
        n += end - max_uint32(start, 0x10000);
    }
    if (string_buffer_init2(ctx, b, n, end >= 0x100))
        return JSI_EXCEPTION;
    for(i = start; i < end; i++) {
        string_buffer_putc(b, i);
    }
    return string_buffer_end(b);
}

