static JSIValue jsi_string_charCodeAt(JSIContext *ctx, JSIValueConst this_val,
                                     int argc, JSIValueConst *argv)
{
    JSIValue val, ret;
    JSIString *p;
    int idx, c;

    val = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(val))
        return val;
    p = JSI_VALUE_GET_STRING(val);
    if (JSI_ToInt32Sat(ctx, &idx, argv[0])) {
        JSI_FreeValue(ctx, val);
        return JSI_EXCEPTION;
    }
    if (idx < 0 || idx >= p->len) {
        ret = JSI_UNDEFINED;
    } else {
        c = string_get(p, idx);
        ret = JSI_NewInt32(ctx, c);
    }
    JSI_FreeValue(ctx, val);
    return ret;
}

static JSIValue jsi_string_charAt(JSIContext *ctx, JSIValueConst this_val,
                                int argc, JSIValueConst *argv, int is_at)
{
    JSIValue val, ret;
    JSIString *p;
    int idx, c;

    val = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(val))
        return val;
    p = JSI_VALUE_GET_STRING(val);
    if (JSI_ToInt32Sat(ctx, &idx, argv[0])) {
        JSI_FreeValue(ctx, val);
        return JSI_EXCEPTION;
    }
    if (idx < 0 && is_at)
        idx += p->len;
    if (idx < 0 || idx >= p->len) {
        if (is_at)
            ret = JSI_UNDEFINED;
        else
            ret = JSI_AtomToString(ctx, JSI_ATOM_empty_string);
    } else {
        c = string_get(p, idx);
        ret = jsi_new_string_char(ctx, c);
    }
    JSI_FreeValue(ctx, val);
    return ret;
}

static JSIValue jsi_string_codePointAt(JSIContext *ctx, JSIValueConst this_val,
                                     int argc, JSIValueConst *argv)
{
    JSIValue val, ret;
    JSIString *p;
    int idx, c;

    val = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(val))
        return val;
    p = JSI_VALUE_GET_STRING(val);
    if (JSI_ToInt32Sat(ctx, &idx, argv[0])) {
        JSI_FreeValue(ctx, val);
        return JSI_EXCEPTION;
    }
    if (idx < 0 || idx >= p->len) {
        ret = JSI_UNDEFINED;
    } else {
        c = string_getc(p, &idx);
        ret = JSI_NewInt32(ctx, c);
    }
    JSI_FreeValue(ctx, val);
    return ret;
}

static JSIValue jsi_string_concat(JSIContext *ctx, JSIValueConst this_val,
                                int argc, JSIValueConst *argv)
{
    JSIValue r;
    int i;

    /* XXX: Use more efficient method */
    /* XXX: This method is OK if r has a single refcount */
    /* XXX: should use string_buffer? */
    r = JSI_ToStringCheckObject(ctx, this_val);
    for (i = 0; i < argc; i++) {
        if (JSI_IsException(r))
            break;
        r = JSI_ConcatString(ctx, r, JSI_DupValue(ctx, argv[i]));
    }
    return r;
}

static int string_cmp(JSIString *p1, JSIString *p2, int x1, int x2, int len)
{
    int i, c1, c2;
    for (i = 0; i < len; i++) {
        if ((c1 = string_get(p1, x1 + i)) != (c2 = string_get(p2, x2 + i)))
            return c1 - c2;
    }
    return 0;
}

static int string_indexof_char(JSIString *p, int c, int from)
{
    /* assuming 0 <= from <= p->len */
    int i, len = p->len;
    if (p->is_wide_char) {
        for (i = from; i < len; i++) {
            if (p->u.str16[i] == c)
                return i;
        }
    } else {
        if ((c & ~0xff) == 0) {
            for (i = from; i < len; i++) {
                if (p->u.str8[i] == (uint8_t)c)
                    return i;
            }
        }
    }
    return -1;
}

static int string_indexof(JSIString *p1, JSIString *p2, int from)
{
    /* assuming 0 <= from <= p1->len */
    int c, i, j, len1 = p1->len, len2 = p2->len;
    if (len2 == 0)
        return from;
    for (i = from, c = string_get(p2, 0); i + len2 <= len1; i = j + 1) {
        j = string_indexof_char(p1, c, i);
        if (j < 0 || j + len2 > len1)
            break;
        if (!string_cmp(p1, p2, j + 1, 1, len2 - 1))
            return j;
    }
    return -1;
}

static int64_t string_advance_index(JSIString *p, int64_t index, BOOL unicode)
{
    if (!unicode || index >= p->len || !p->is_wide_char) {
        index++;
    } else {
        int index32 = (int)index;
        string_getc(p, &index32);
        index = index32;
    }
    return index;
}

/* return the position of the first invalid character in the string or
   -1 if none */
static int jsi_string_find_invalid_codepoint(JSIString *p)
{
    int i;
    if (!p->is_wide_char)
        return -1;
    for(i = 0; i < p->len; i++) {
        uint32_t c = p->u.str16[i];
        if (is_surrogate(c)) {
            if (is_hi_surrogate(c) && (i + 1) < p->len
            &&  is_lo_surrogate(p->u.str16[i + 1])) {
                i++;
            } else {
                return i;
            }
        }
    }
    return -1;
}

static JSIValue jsi_string_isWellFormed(JSIContext *ctx, JSIValueConst this_val,
                                      int argc, JSIValueConst *argv)
{
    JSIValue str;
    JSIString *p;
    BOOL ret;

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        return JSI_EXCEPTION;
    p = JSI_VALUE_GET_STRING(str);
    ret = (jsi_string_find_invalid_codepoint(p) < 0);
    JSI_FreeValue(ctx, str);
    return JSI_NewBool(ctx, ret);
}

static JSIValue jsi_string_toWellFormed(JSIContext *ctx, JSIValueConst this_val,
                                      int argc, JSIValueConst *argv)
{
    JSIValue str, ret;
    JSIString *p;
    int i;

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        return JSI_EXCEPTION;

    p = JSI_VALUE_GET_STRING(str);
    /* avoid reallocating the string if it is well-formed */
    i = jsi_string_find_invalid_codepoint(p);
    if (i < 0)
        return str;

    ret = jsi_new_string16_len(ctx, p->u.str16, p->len);
    JSI_FreeValue(ctx, str);
    if (JSI_IsException(ret))
        return JSI_EXCEPTION;

    p = JSI_VALUE_GET_STRING(ret);
    for (; i < p->len; i++) {
        uint32_t c = p->u.str16[i];
        if (is_surrogate(c)) {
            if (is_hi_surrogate(c) && (i + 1) < p->len
            &&  is_lo_surrogate(p->u.str16[i + 1])) {
                i++;
            } else {
                p->u.str16[i] = 0xFFFD;
            }
        }
    }
    return ret;
}

static JSIValue jsi_string_indexOf(JSIContext *ctx, JSIValueConst this_val,
                                 int argc, JSIValueConst *argv, int lastIndexOf)
{
    JSIValue str, v;
    int i, len, v_len, pos, start, stop, ret, inc;
    JSIString *p;
    JSIString *p1;

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        return str;
    v = JSI_ToString(ctx, argv[0]);
    if (JSI_IsException(v))
        goto fail;
    p = JSI_VALUE_GET_STRING(str);
    p1 = JSI_VALUE_GET_STRING(v);
    len = p->len;
    v_len = p1->len;
    if (lastIndexOf) {
        pos = len - v_len;
        if (argc > 1) {
            int64_t d;
            if (JSI_ToInt64(ctx, &d, argv[1]))
                goto fail;
        }
        start = pos;
        stop = 0;
        inc = -1;
    } else {
        pos = 0;
        if (argc > 1) {
            if (JSI_ToInt32Clamp(ctx, &pos, argv[1], 0, len, 0))
                goto fail;
        }
        start = pos;
        stop = len - v_len;
        inc = 1;
    }
    ret = -1;
    if (len >= v_len && inc * (stop - start) >= 0) {
        for (i = start;; i += inc) {
            if (!string_cmp(p, p1, i, 0, v_len)) {
                ret = i;
                break;
            }
            if (i == stop)
                break;
        }
    }
    JSI_FreeValue(ctx, str);
    JSI_FreeValue(ctx, v);
    return JSI_NewInt32(ctx, ret);

fail:
    JSI_FreeValue(ctx, str);
    JSI_FreeValue(ctx, v);
    return JSI_EXCEPTION;
}

/* return < 0 if exception or TRUE/FALSE */

static JSIValue jsi_string_includes(JSIContext *ctx, JSIValueConst this_val,
                                  int argc, JSIValueConst *argv, int magic)
{
    JSIValue str, v = JSI_UNDEFINED;
    int i, len, v_len, pos, start, stop, ret;
    JSIString *p;
    JSIString *p1;

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        return str;
    v = JSI_ToString(ctx, argv[0]);
    if (JSI_IsException(v))
        goto fail;
    p = JSI_VALUE_GET_STRING(str);
    p1 = JSI_VALUE_GET_STRING(v);
    len = p->len;
    v_len = p1->len;
    pos = (magic == 2) ? len : 0;
    if (argc > 1 && !JSI_IsUndefined(argv[1])) {
        if (JSI_ToInt32Clamp(ctx, &pos, argv[1], 0, len, 0))
            goto fail;
    }
    len -= v_len;
    ret = 0;
    if (magic == 0) {
        start = pos;
        stop = len;
    } else {
        if (magic == 1) {
            if (pos > len)
                goto done;
        } else {
            pos -= v_len;
        }
        start = stop = pos;
    }
    if (start >= 0 && start <= stop) {
        for (i = start;; i++) {
            if (!string_cmp(p, p1, i, 0, v_len)) {
                ret = 1;
                break;
            }
            if (i == stop)
                break;
        }
    }
 done:
    JSI_FreeValue(ctx, str);
    JSI_FreeValue(ctx, v);
    return JSI_NewBool(ctx, ret);

fail:
    JSI_FreeValue(ctx, str);
    JSI_FreeValue(ctx, v);
    return JSI_EXCEPTION;
}



static JSIValue jsi_string___GetSubstitution(JSIContext *ctx, JSIValueConst this_val,
                                           int argc, JSIValueConst *argv)
{
    // GetSubstitution(matched, str, position, captures, namedCaptures, rep)
    JSIValueConst matched, str, captures, namedCaptures, rep;
    JSIValue capture, name, s;
    uint32_t position, len, matched_len, captures_len;
    int i, j, j0, k, k1;
    int c, c1;
    StringBuffer b_s, *b = &b_s;
    JSIString *sp, *rp;

    matched = argv[0];
    str = argv[1];
    captures = argv[3];
    namedCaptures = argv[4];
    rep = argv[5];

    if (!JSI_IsString(rep) || !JSI_IsString(str))
        return JSI_ThrowTypeError(ctx, "not a string");

    sp = JSI_VALUE_GET_STRING(str);
    rp = JSI_VALUE_GET_STRING(rep);

    string_buffer_init(ctx, b, 0);

    captures_len = 0;
    if (!JSI_IsUndefined(captures)) {
        if (jsi_get_length32(ctx, &captures_len, captures))
            goto exception;
    }
    if (jsi_get_length32(ctx, &matched_len, matched))
        goto exception;
    if (JSI_ToUint32(ctx, &position, argv[2]) < 0)
        goto exception;

    len = rp->len;
    i = 0;
    for(;;) {
        j = string_indexof_char(rp, '$', i);
        if (j < 0 || j + 1 >= len)
            break;
        string_buffer_concat(b, rp, i, j);
        j0 = j++;
        c = string_get(rp, j++);
        if (c == '$') {
            string_buffer_putc8(b, '$');
        } else if (c == '&') {
            if (string_buffer_concat_value(b, matched))
                goto exception;
        } else if (c == '`') {
            string_buffer_concat(b, sp, 0, position);
        } else if (c == '\'') {
            string_buffer_concat(b, sp, position + matched_len, sp->len);
        } else if (c >= '0' && c <= '9') {
            k = c - '0';
            if (j < len) {
                c1 = string_get(rp, j);
                if (c1 >= '0' && c1 <= '9') {
                    /* This behavior is specified in ES6 and refined in ECMA 2019 */
                    /* ECMA 2019 does not have the extra test, but
                       Test262 S15.5.4.11_A3_T1..3 require this behavior */
                    k1 = k * 10 + c1 - '0';
                    if (k1 >= 1 && k1 < captures_len) {
                        k = k1;
                        j++;
                    }
                }
            }
            if (k >= 1 && k < captures_len) {
                s = JSI_GetPropertyInt64(ctx, captures, k);
                if (JSI_IsException(s))
                    goto exception;
                if (!JSI_IsUndefined(s)) {
                    if (string_buffer_concat_value_free(b, s))
                        goto exception;
                }
            } else {
                goto norep;
            }
        } else if (c == '<' && !JSI_IsUndefined(namedCaptures)) {
            k = string_indexof_char(rp, '>', j);
            if (k < 0)
                goto norep;
            name = jsi_sub_string(ctx, rp, j, k);
            if (JSI_IsException(name))
                goto exception;
            capture = JSI_GetPropertyValue(ctx, namedCaptures, name);
            if (JSI_IsException(capture))
                goto exception;
            if (!JSI_IsUndefined(capture)) {
                if (string_buffer_concat_value_free(b, capture))
                    goto exception;
            }
            j = k + 1;
        } else {
        norep:
            string_buffer_concat(b, rp, j0, j);
        }
        i = j;
    }
    string_buffer_concat(b, rp, i, rp->len);
    return string_buffer_end(b);
exception:
    string_buffer_free(b);
    return JSI_EXCEPTION;
}


static JSIValue jsi_string_split(JSIContext *ctx, JSIValueConst this_val,
                               int argc, JSIValueConst *argv)
{
    // split(sep, limit)
    JSIValueConst O = this_val, separator = argv[0], limit = argv[1];
    JSIValueConst args[2];
    JSIValue S, A, R, T;
    uint32_t lim, lengthA;
    int64_t p, q, s, r, e;
    JSIString *sp, *rp;

    if (JSI_IsUndefined(O) || JSI_IsNull(O))
        return JSI_ThrowTypeError(ctx, "cannot convert to object");

    S = JSI_UNDEFINED;
    A = JSI_UNDEFINED;
    R = JSI_UNDEFINED;

    if (!JSI_IsUndefined(separator) && !JSI_IsNull(separator)) {
        JSIValue splitter;
        splitter = JSI_GetProperty(ctx, separator, JSI_ATOM_Symbol_split);
        if (JSI_IsException(splitter))
            return JSI_EXCEPTION;
        if (!JSI_IsUndefined(splitter) && !JSI_IsNull(splitter)) {
            args[0] = O;
            args[1] = limit;
            return JSI_CallFree(ctx, splitter, separator, 2, args);
        }
    }
    S = JSI_ToString(ctx, O);
    if (JSI_IsException(S))
        goto exception;
    A = JSI_NewArray(ctx);
    if (JSI_IsException(A))
        goto exception;
    lengthA = 0;
    if (JSI_IsUndefined(limit)) {
        lim = 0xffffffff;
    } else {
        if (JSI_ToUint32(ctx, &lim, limit) < 0)
            goto exception;
    }
    sp = JSI_VALUE_GET_STRING(S);
    s = sp->len;
    R = JSI_ToString(ctx, separator);
    if (JSI_IsException(R))
        goto exception;
    rp = JSI_VALUE_GET_STRING(R);
    r = rp->len;
    p = 0;
    if (lim == 0)
        goto done;
    if (JSI_IsUndefined(separator))
        goto add_tail;
    if (s == 0) {
        if (r != 0)
            goto add_tail;
        goto done;
    }
    q = p;
    for (q = p; (q += !r) <= s - r - !r; q = p = e + r) {
        e = string_indexof(sp, rp, q);
        if (e < 0)
            break;
        T = jsi_sub_string(ctx, sp, p, e);
        if (JSI_IsException(T))
            goto exception;
        if (JSI_CreateDataPropertyUint32(ctx, A, lengthA++, T, 0) < 0)
            goto exception;
        if (lengthA == lim)
            goto done;
    }
add_tail:
    T = jsi_sub_string(ctx, sp, p, s);
    if (JSI_IsException(T))
        goto exception;
    if (JSI_CreateDataPropertyUint32(ctx, A, lengthA++, T,0 ) < 0)
        goto exception;
done:
    JSI_FreeValue(ctx, S);
    JSI_FreeValue(ctx, R);
    return A;

exception:
    JSI_FreeValue(ctx, A);
    JSI_FreeValue(ctx, S);
    JSI_FreeValue(ctx, R);
    return JSI_EXCEPTION;
}

static JSIValue jsi_string_substring(JSIContext *ctx, JSIValueConst this_val,
                                   int argc, JSIValueConst *argv)
{
    JSIValue str, ret;
    int a, b, start, end;
    JSIString *p;

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        return str;
    p = JSI_VALUE_GET_STRING(str);
    if (JSI_ToInt32Clamp(ctx, &a, argv[0], 0, p->len, 0)) {
        JSI_FreeValue(ctx, str);
        return JSI_EXCEPTION;
    }
    b = p->len;
    if (!JSI_IsUndefined(argv[1])) {
        if (JSI_ToInt32Clamp(ctx, &b, argv[1], 0, p->len, 0)) {
            JSI_FreeValue(ctx, str);
            return JSI_EXCEPTION;
        }
    }
    if (a < b) {
        start = a;
        end = b;
    } else {
        start = b;
        end = a;
    }
    ret = jsi_sub_string(ctx, p, start, end);
    JSI_FreeValue(ctx, str);
    return ret;
}

static JSIValue jsi_string_substr(JSIContext *ctx, JSIValueConst this_val,
                                int argc, JSIValueConst *argv)
{
    JSIValue str, ret;
    int a, len, n;
    JSIString *p;

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        return str;
    p = JSI_VALUE_GET_STRING(str);
    len = p->len;
    if (JSI_ToInt32Clamp(ctx, &a, argv[0], 0, len, len)) {
        JSI_FreeValue(ctx, str);
        return JSI_EXCEPTION;
    }
    n = len - a;
    if (!JSI_IsUndefined(argv[1])) {
        if (JSI_ToInt32Clamp(ctx, &n, argv[1], 0, len - a, 0)) {
            JSI_FreeValue(ctx, str);
            return JSI_EXCEPTION;
        }
    }
    ret = jsi_sub_string(ctx, p, a, a + n);
    JSI_FreeValue(ctx, str);
    return ret;
}

static JSIValue jsi_string_slice(JSIContext *ctx, JSIValueConst this_val,
                               int argc, JSIValueConst *argv)
{
    JSIValue str, ret;
    int len, start, end;
    JSIString *p;

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        return str;
    p = JSI_VALUE_GET_STRING(str);
    len = p->len;
    if (JSI_ToInt32Clamp(ctx, &start, argv[0], 0, len, len)) {
        JSI_FreeValue(ctx, str);
        return JSI_EXCEPTION;
    }
    end = len;
    if (!JSI_IsUndefined(argv[1])) {
        if (JSI_ToInt32Clamp(ctx, &end, argv[1], 0, len, len)) {
            JSI_FreeValue(ctx, str);
            return JSI_EXCEPTION;
        }
    }
    ret = jsi_sub_string(ctx, p, start, max_int(end, start));
    JSI_FreeValue(ctx, str);
    return ret;
}

static JSIValue jsi_string_pad(JSIContext *ctx, JSIValueConst this_val,
                             int argc, JSIValueConst *argv, int padEnd)
{
    JSIValue str, v = JSI_UNDEFINED;
    StringBuffer b_s, *b = &b_s;
    JSIString *p, *p1 = NULL;
    int n, len, c = ' ';

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        goto fail1;
    if (JSI_ToInt32Sat(ctx, &n, argv[0]))
        goto fail2;
    p = JSI_VALUE_GET_STRING(str);
    len = p->len;
    if (len >= n)
        return str;
    if (argc > 1 && !JSI_IsUndefined(argv[1])) {
        v = JSI_ToString(ctx, argv[1]);
        if (JSI_IsException(v))
            goto fail2;
        p1 = JSI_VALUE_GET_STRING(v);
        if (p1->len == 0) {
            JSI_FreeValue(ctx, v);
            return str;
        }
        if (p1->len == 1) {
            c = string_get(p1, 0);
            p1 = NULL;
        }
    }
    if (n > JSI_STRING_LEN_MAX) {
        JSI_ThrowRangeError(ctx, "invalid string length");
        goto fail3;
    }
    if (string_buffer_init(ctx, b, n))
        goto fail3;
    n -= len;
    if (padEnd) {
        if (string_buffer_concat(b, p, 0, len))
            goto fail;
    }
    if (p1) {
        while (n > 0) {
            int chunk = min_int(n, p1->len);
            if (string_buffer_concat(b, p1, 0, chunk))
                goto fail;
            n -= chunk;
        }
    } else {
        if (string_buffer_fill(b, c, n))
            goto fail;
    }
    if (!padEnd) {
        if (string_buffer_concat(b, p, 0, len))
            goto fail;
    }
    JSI_FreeValue(ctx, v);
    JSI_FreeValue(ctx, str);
    return string_buffer_end(b);

fail:
    string_buffer_free(b);
fail3:
    JSI_FreeValue(ctx, v);
fail2:
    JSI_FreeValue(ctx, str);
fail1:
    return JSI_EXCEPTION;
}

static JSIValue jsi_string_repeat(JSIContext *ctx, JSIValueConst this_val,
                                int argc, JSIValueConst *argv)
{
    JSIValue str;
    StringBuffer b_s, *b = &b_s;
    JSIString *p;
    int64_t val;
    int n, len;

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        goto fail;
    if (JSI_ToInt64Sat(ctx, &val, argv[0]))
        goto fail;
    if (val < 0 || val > 2147483647) {
        JSI_ThrowRangeError(ctx, "invalid repeat count");
        goto fail;
    }
    n = val;
    p = JSI_VALUE_GET_STRING(str);
    len = p->len;
    if (len == 0 || n == 1)
        return str;
    // XXX: potential arithmetic overflow
    if (val * len > JSI_STRING_LEN_MAX) {
        JSI_ThrowRangeError(ctx, "invalid string length");
        goto fail;
    }
    if (string_buffer_init2(ctx, b, n * len, p->is_wide_char))
        goto fail;
    if (len == 1) {
        string_buffer_fill(b, string_get(p, 0), n);
    } else {
        while (n-- > 0) {
            string_buffer_concat(b, p, 0, len);
        }
    }
    JSI_FreeValue(ctx, str);
    return string_buffer_end(b);

fail:
    JSI_FreeValue(ctx, str);
    return JSI_EXCEPTION;
}

static JSIValue jsi_string_trim(JSIContext *ctx, JSIValueConst this_val,
                              int argc, JSIValueConst *argv, int magic)
{
    JSIValue str, ret;
    int a, b, len;
    JSIString *p;

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        return str;
    p = JSI_VALUE_GET_STRING(str);
    a = 0;
    b = len = p->len;
    if (magic & 1) {
        while (a < len && lre_jsi_is_space(string_get(p, a)))
            a++;
    }
    if (magic & 2) {
        while (b > a && lre_jsi_is_space(string_get(p, b - 1)))
            b--;
    }
    ret = jsi_sub_string(ctx, p, a, b);
    JSI_FreeValue(ctx, str);
    return ret;
}

static JSIValue jsi_string___quote(JSIContext *ctx, JSIValueConst this_val,
                                 int argc, JSIValueConst *argv)
{
    return JSI_ToQuotedString(ctx, this_val);
}

/* return 0 if before the first char */
static int string_prevc(JSIString *p, int *pidx)
{
    int idx, c, c1;

    idx = *pidx;
    if (idx <= 0)
        return 0;
    idx--;
    if (p->is_wide_char) {
        c = p->u.str16[idx];
        if (is_lo_surrogate(c) && idx > 0) {
            c1 = p->u.str16[idx - 1];
            if (is_hi_surrogate(c1)) {
                c = from_surrogate(c1, c);
                idx--;
            }
        }
    } else {
        c = p->u.str8[idx];
    }
    *pidx = idx;
    return c;
}

static BOOL test_final_sigma(JSIString *p, int sigma_pos)
{
    int k, c1;

    /* before C: skip case ignorable chars and check there is
       a cased letter */
    k = sigma_pos;
    for(;;) {
        c1 = string_prevc(p, &k);
        if (!lre_jsi_is_case_ignorable(c1))
            break;
    }
    if (!lre_jsi_is_cased(c1))
        return FALSE;

    /* after C: skip case ignorable chars and check there is
       no cased letter */
    k = sigma_pos + 1;
    for(;;) {
        if (k >= p->len)
            return TRUE;
        c1 = string_getc(p, &k);
        if (!lre_jsi_is_case_ignorable(c1))
            break;
    }
    return !lre_jsi_is_cased(c1);
}

static JSIValue jsi_string_toLowerCase(JSIContext *ctx, JSIValueConst this_val,
                                     int argc, JSIValueConst *argv, int to_lower)
{
    JSIValue val;
    StringBuffer b_s, *b = &b_s;
    JSIString *p;
    int i, c, j, l;
    uint32_t res[LRE_CC_RES_LEN_MAX];

    val = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(val))
        return val;
    p = JSI_VALUE_GET_STRING(val);
    if (p->len == 0)
        return val;
    if (string_buffer_init(ctx, b, p->len))
        goto fail;
    for(i = 0; i < p->len;) {
        c = string_getc(p, &i);
        if (c == 0x3a3 && to_lower && test_final_sigma(p, i - 1)) {
            res[0] = 0x3c2; /* final sigma */
            l = 1;
        } else {
            l = lre_jsi_case_conv(res, c, to_lower);
        }
        for(j = 0; j < l; j++) {
            if (string_buffer_putc(b, res[j]))
                goto fail;
        }
    }
    JSI_FreeValue(ctx, val);
    return string_buffer_end(b);
 fail:
    JSI_FreeValue(ctx, val);
    string_buffer_free(b);
    return JSI_EXCEPTION;
}

#ifdef CONFIG_ALL_UNICODE

/* return (-1, NULL) if exception, otherwise (len, buf) */
static int JSI_ToUTF32String(JSIContext *ctx, uint32_t **pbuf, JSIValueConst val1)
{
    JSIValue val;
    JSIString *p;
    uint32_t *buf;
    int i, j, len;

    val = JSI_ToString(ctx, val1);
    if (JSI_IsException(val))
        return -1;
    p = JSI_VALUE_GET_STRING(val);
    len = p->len;
    /* UTF32 buffer length is len minus the number of correct surrogates pairs */
    buf = jsi_malloc(ctx, sizeof(buf[0]) * max_int(len, 1));
    if (!buf) {
        JSI_FreeValue(ctx, val);
        goto fail;
    }
    for(i = j = 0; i < len;)
        buf[j++] = string_getc(p, &i);
    JSI_FreeValue(ctx, val);
    *pbuf = buf;
    return j;
 fail:
    *pbuf = NULL;
    return -1;
}

static JSIValue JSI_NewUTF32String(JSIContext *ctx, const uint32_t *buf, int len)
{
    int i;
    StringBuffer b_s, *b = &b_s;
    if (string_buffer_init(ctx, b, len))
        return JSI_EXCEPTION;
    for(i = 0; i < len; i++) {
        if (string_buffer_putc(b, buf[i]))
            goto fail;
    }
    return string_buffer_end(b);
 fail:
    string_buffer_free(b);
    return JSI_EXCEPTION;
}

static int jsi_string_normalize1(JSIContext *ctx, uint32_t **pout_buf,
                                JSIValueConst val,
                                UnicodeNormalizationEnum n_type)
{
    int buf_len, out_len;
    uint32_t *buf, *out_buf;

    buf_len = JSI_ToUTF32String(ctx, &buf, val);
    if (buf_len < 0)
        return -1;
    out_len = unicode_jsi_normalize(&out_buf, buf, buf_len, n_type,
                                ctx->rt, (DynBufReallocFunc *)jsi_realloc_rt);
    jsi_free(ctx, buf);
    if (out_len < 0)
        return -1;
    *pout_buf = out_buf;
    return out_len;
}

static JSIValue jsi_string_normalize(JSIContext *ctx, JSIValueConst this_val,
                                   int argc, JSIValueConst *argv)
{
    const char *form, *p;
    size_t form_len;
    int is_compat, out_len;
    UnicodeNormalizationEnum n_type;
    JSIValue val;
    uint32_t *out_buf;

    val = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(val))
        return val;

    if (argc == 0 || JSI_IsUndefined(argv[0])) {
        n_type = UNICODE_NFC;
    } else {
        form = JSI_ToCStringLen(ctx, &form_len, argv[0]);
        if (!form)
            goto fail1;
        p = form;
        if (p[0] != 'N' || p[1] != 'F')
            goto bad_form;
        p += 2;
        is_compat = FALSE;
        if (*p == 'K') {
            is_compat = TRUE;
            p++;
        }
        if (*p == 'C' || *p == 'D') {
            n_type = UNICODE_NFC + is_compat * 2 + (*p - 'C');
            if ((p + 1 - form) != form_len)
                goto bad_form;
        } else {
        bad_form:
            JSI_FreeCString(ctx, form);
            JSI_ThrowRangeError(ctx, "bad normalization form");
        fail1:
            JSI_FreeValue(ctx, val);
            return JSI_EXCEPTION;
        }
        JSI_FreeCString(ctx, form);
    }

    out_len = jsi_string_normalize1(ctx, &out_buf, val, n_type);
    JSI_FreeValue(ctx, val);
    if (out_len < 0)
        return JSI_EXCEPTION;
    val = JSI_NewUTF32String(ctx, out_buf, out_len);
    jsi_free(ctx, out_buf);
    return val;
}

/* return < 0, 0 or > 0 */
static int jsi_UTF32_compare(const uint32_t *buf1, int buf1_len,
                            const uint32_t *buf2, int buf2_len)
{
    int i, len, c, res;
    len = min_int(buf1_len, buf2_len);
    for(i = 0; i < len; i++) {
        /* Note: range is limited so a subtraction is valid */
        c = buf1[i] - buf2[i];
        if (c != 0)
            return c;
    }
    if (buf1_len == buf2_len)
        res = 0;
    else if (buf1_len < buf2_len)
        res = -1;
    else
        res = 1;
    return res;
}

static JSIValue jsi_string_localeCompare(JSIContext *ctx, JSIValueConst this_val,
                                       int argc, JSIValueConst *argv)
{
    JSIValue a, b;
    int cmp, a_len, b_len;
    uint32_t *a_buf, *b_buf;

    a = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(a))
        return JSI_EXCEPTION;
    b = JSI_ToString(ctx, argv[0]);
    if (JSI_IsException(b)) {
        JSI_FreeValue(ctx, a);
        return JSI_EXCEPTION;
    }
    a_len = jsi_string_normalize1(ctx, &a_buf, a, UNICODE_NFC);
    JSI_FreeValue(ctx, a);
    if (a_len < 0) {
        JSI_FreeValue(ctx, b);
        return JSI_EXCEPTION;
    }

    b_len = jsi_string_normalize1(ctx, &b_buf, b, UNICODE_NFC);
    JSI_FreeValue(ctx, b);
    if (b_len < 0) {
        jsi_free(ctx, a_buf);
        return JSI_EXCEPTION;
    }
    cmp = jsi_UTF32_compare(a_buf, a_len, b_buf, b_len);
    jsi_free(ctx, a_buf);
    jsi_free(ctx, b_buf);
    return JSI_NewInt32(ctx, cmp);
}
#else /* CONFIG_ALL_UNICODE */
static JSIValue jsi_string_localeCompare(JSIContext *ctx, JSIValueConst this_val,
                                       int argc, JSIValueConst *argv)
{
    JSIValue a, b;
    int cmp;

    a = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(a))
        return JSI_EXCEPTION;
    b = JSI_ToString(ctx, argv[0]);
    if (JSI_IsException(b)) {
        JSI_FreeValue(ctx, a);
        return JSI_EXCEPTION;
    }
    cmp = jsi_string_compare(ctx, JSI_VALUE_GET_STRING(a), JSI_VALUE_GET_STRING(b));
    JSI_FreeValue(ctx, a);
    JSI_FreeValue(ctx, b);
    return JSI_NewInt32(ctx, cmp);
}
#endif /* !CONFIG_ALL_UNICODE */

