static JSIValue jsi_string___advanceStringIndex(JSIContext *ctx, JSIValueConst
                                              this_val,
                                              int argc, JSIValueConst *argv)
{
    JSIValue str;
    int idx;
    BOOL is_unicode;
    JSIString *p;

    str = JSI_ToString(ctx, argv[0]);
    if (JSI_IsException(str))
        return str;
    if (JSI_ToInt32Sat(ctx, &idx, argv[1])) {
        JSI_FreeValue(ctx, str);
        return JSI_EXCEPTION;
    }
    is_unicode = JSI_ToBool(ctx, argv[2]);
    p = JSI_VALUE_GET_STRING(str);
    if (!is_unicode || (unsigned)idx >= p->len || !p->is_wide_char) {
        idx++;
    } else {
        string_getc(p, &idx);
    }
    JSI_FreeValue(ctx, str);
    return JSI_NewInt32(ctx, idx);
}
