/* String Iterator */

static JSIValue jsi_string_iterator_next(JSIContext *ctx, JSIValueConst this_val,
                                       int argc, JSIValueConst *argv,
                                       BOOL *pdone, int magic)
{
    JSArrayIteratorData *it;
    uint32_t idx, c, start;
    JSIString *p;

    it = JSI_GetOpaque2(ctx, this_val, JSI_CLASS_STRING_ITERATOR);
    if (!it) {
        *pdone = FALSE;
        return JSI_EXCEPTION;
    }
    if (JSI_IsUndefined(it->obj))
        goto done;
    p = JSI_VALUE_GET_STRING(it->obj);
    idx = it->idx;
    if (idx >= p->len) {
        JSI_FreeValue(ctx, it->obj);
        it->obj = JSI_UNDEFINED;
    done:
        *pdone = TRUE;
        return JSI_UNDEFINED;
    }

    start = idx;
    c = string_getc(p, (int *)&idx);
    it->idx = idx;
    *pdone = FALSE;
    if (c <= 0xffff) {
        return jsi_new_string_char(ctx, c);
    } else {
        return jsi_new_string16_len(ctx, p->u.str16 + start, 2);
    }
}

/* ES6 Annex B 2.3.2 etc. */
enum {
    magic_string_anchor,
    magic_string_big,
    magic_string_blink,
    magic_string_bold,
    magic_string_fixed,
    magic_string_fontcolor,
    magic_string_fontsize,
    magic_string_italics,
    magic_string_link,
    magic_string_small,
    magic_string_strike,
    magic_string_sub,
    magic_string_sup,
};

static JSIValue jsi_string_CreateHTML(JSIContext *ctx, JSIValueConst this_val,
                                    int argc, JSIValueConst *argv, int magic)
{
    JSIValue str;
    const JSIString *p;
    StringBuffer b_s, *b = &b_s;
    static struct { const char *tag, *attr; } const defs[] = {
        { "a", "name" }, { "big", NULL }, { "blink", NULL }, { "b", NULL },
        { "tt", NULL }, { "font", "color" }, { "font", "size" }, { "i", NULL },
        { "a", "href" }, { "small", NULL }, { "strike", NULL },
        { "sub", NULL }, { "sup", NULL },
    };

    str = JSI_ToStringCheckObject(ctx, this_val);
    if (JSI_IsException(str))
        return JSI_EXCEPTION;
    string_buffer_init(ctx, b, 7);
    string_buffer_putc8(b, '<');
    string_buffer_puts8(b, defs[magic].tag);
    if (defs[magic].attr) {
        // r += " " + attr + "=\"" + value + "\"";
        JSIValue value;
        int i;

        string_buffer_putc8(b, ' ');
        string_buffer_puts8(b, defs[magic].attr);
        string_buffer_puts8(b, "=\"");
        value = JSI_ToStringCheckObject(ctx, argv[0]);
        if (JSI_IsException(value)) {
            JSI_FreeValue(ctx, str);
            string_buffer_free(b);
            return JSI_EXCEPTION;
        }
        p = JSI_VALUE_GET_STRING(value);
        for (i = 0; i < p->len; i++) {
            int c = string_get(p, i);
            if (c == '"') {
                string_buffer_puts8(b, "&quot;");
            } else {
                string_buffer_putc16(b, c);
            }
        }
        JSI_FreeValue(ctx, value);
        string_buffer_putc8(b, '\"');
    }
    // return r + ">" + str + "</" + tag + ">";
    string_buffer_putc8(b, '>');
    string_buffer_concat_value_free(b, str);
    string_buffer_puts8(b, "</");
    string_buffer_puts8(b, defs[magic].tag);
    string_buffer_putc8(b, '>');
    return string_buffer_end(b);
}

