/* RegExp */


int lre_jsi_check_stack_overflow(void *opaque, size_t alloca_size)
{
    JSIContext *ctx = opaque;
    return jsi_check_stack_overflow(ctx->rt, alloca_size);
}

int lre_jsi_check_timeout(void *opaque)
{
    JSIContext *ctx = opaque;
    JSIRuntime *rt = ctx->rt;
    return (rt->interrupt_handler && 
            rt->interrupt_handler(rt, rt->interrupt_opaque));
}

void *lre_jsi_realloc(void *opaque, void *ptr, size_t size)
{
    JSIContext *ctx = opaque;
    /* No JS exception is raised here */
    return jsi_realloc_rt(ctx->rt, ptr, size);
}

typedef struct ValueBuffer {
    JSIContext *ctx;
    JSIValue *arr;
    JSIValue def[4];
    int len;
    int size;
    int error_status;
} ValueBuffer;

static int value_buffer_init(JSIContext *ctx, ValueBuffer *b)
{
    b->ctx = ctx;
    b->len = 0;
    b->size = 4;
    b->error_status = 0;
    b->arr = b->def;
    return 0;
}

static void value_buffer_free(ValueBuffer *b)
{
    while (b->len > 0)
        JSI_FreeValue(b->ctx, b->arr[--b->len]);
    if (b->arr != b->def)
        jsi_free(b->ctx, b->arr);
    b->arr = b->def;
    b->size = 4;
}

static int value_buffer_append(ValueBuffer *b, JSIValue val)
{
    if (b->error_status)
        return -1;

    if (b->len >= b->size) {
        int new_size = (b->len + (b->len >> 1) + 31) & ~16;
        size_t slack;
        JSIValue *new_arr;

        if (b->arr == b->def) {
            new_arr = jsi_realloc2(b->ctx, NULL, sizeof(*b->arr) * new_size, &slack);
            if (new_arr)
                memcpy(new_arr, b->def, sizeof b->def);
        } else {
            new_arr = jsi_realloc2(b->ctx, b->arr, sizeof(*b->arr) * new_size, &slack);
        }
        if (!new_arr) {
            value_buffer_free(b);
            JSI_FreeValue(b->ctx, val);
            b->error_status = -1;
            return -1;
        }
        new_size += slack / sizeof(*new_arr);
        b->arr = new_arr;
        b->size = new_size;
    }
    b->arr[b->len++] = val;
    return 0;
}




/* JSON */



static JSIValue internalize_json_property(JSIContext *ctx, JSIValueConst holder,
                                         JSAtom name, JSIValueConst reviver)
{
    JSIValue val, new_el, name_val, res;
    JSIValueConst args[2];
    int ret, is_array;
    uint32_t i, len = 0;
    JSAtom prop;
    JSIPropertyEnum *atoms = NULL;

    if (jsi_check_stack_overflow(ctx->rt, 0)) {
        return JSI_ThrowStackOverflow(ctx);
    }

    val = JSI_GetProperty(ctx, holder, name);
    if (JSI_IsException(val))
        return val;
    if (JSI_IsObject(val)) {
        is_array = JSI_IsArray(ctx, val);
        if (is_array < 0)
            goto fail;
        if (is_array) {
            if (jsi_get_length32(ctx, &len, val))
                goto fail;
        } else {
            ret = JSI_GetOwnPropertyNamesInternal(ctx, &atoms, &len, JSI_VALUE_GET_OBJ(val), JSI_GPN_ENUM_ONLY | JSI_GPN_STRING_MASK);
            if (ret < 0)
                goto fail;
        }
        for(i = 0; i < len; i++) {
            if (is_array) {
                prop = JSI_NewAtomUInt32(ctx, i);
                if (prop == JSI_ATOM_NULL)
                    goto fail;
            } else {
                prop = JSI_DupAtom(ctx, atoms[i].atom);
            }
            new_el = internalize_json_property(ctx, val, prop, reviver);
            if (JSI_IsException(new_el)) {
                JSI_FreeAtom(ctx, prop);
                goto fail;
            }
            if (JSI_IsUndefined(new_el)) {
                ret = JSI_DeleteProperty(ctx, val, prop, 0);
            } else {
                ret = JSI_DefinePropertyValue(ctx, val, prop, new_el, JSI_PROP_C_W_E);
            }
            JSI_FreeAtom(ctx, prop);
            if (ret < 0)
                goto fail;
        }
    }
    JSI_FreePropertyEnum(ctx, atoms, len);
    atoms = NULL;
    name_val = JSI_AtomToValue(ctx, name);
    if (JSI_IsException(name_val))
        goto fail;
    args[0] = name_val;
    args[1] = val;
    res = JSI_Call(ctx, reviver, holder, 2, args);
    JSI_FreeValue(ctx, name_val);
    JSI_FreeValue(ctx, val);
    return res;
 fail:
    JSI_FreePropertyEnum(ctx, atoms, len);
    JSI_FreeValue(ctx, val);
    return JSI_EXCEPTION;
}


