/* URI handling */

static int string_get_hex(JSIString *p, int k, int n) {
    int c = 0, h;
    while (n-- > 0) {
        if ((h = from_hex(string_get(p, k++))) < 0)
            return -1;
        c = (c << 4) | h;
    }
    return c;
}

static int isURIReserved(int c) {
    return c < 0x100 && memchr(";/?:@&=+$,#", c, sizeof(";/?:@&=+$,#") - 1) != NULL;
}

static int __attribute__((format(printf, 2, 3))) jsi_throw_URIError(JSIContext *ctx, const char *fmt, ...)
{
    va_list ap;

    va_start(ap, fmt);
    JSI_ThrowError(ctx, JSI_URI_ERROR, fmt, ap);
    va_end(ap);
    return -1;
}

static int hex_decode(JSIContext *ctx, JSIString *p, int k) {
    int c;

    if (k >= p->len || string_get(p, k) != '%')
        return jsi_throw_URIError(ctx, "expecting %%");
    if (k + 2 >= p->len || (c = string_get_hex(p, k + 1, 2)) < 0)
        return jsi_throw_URIError(ctx, "expecting hex digit");

    return c;
}


static int isUnescaped(int c) {
    static char const unescaped_chars[] =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz"
        "0123456789"
        "@*_+-./";
    return c < 0x100 &&
        memchr(unescaped_chars, c, sizeof(unescaped_chars) - 1);
}



