/* Minimum amount of objects to be able to compile code and display
   error messages. No JSAtom should be allocated by this function. */
static void JSI_AddIntrinsicBasicObjects(JSIContext *ctx)
{
    JSIValue proto;
    int i;

    ctx->class_proto[JSI_CLASS_OBJECT] = JSI_NewObjectProto(ctx, JSI_NULL);
    JSI_SetImmutablePrototype(ctx, ctx->class_proto[JSI_CLASS_OBJECT]);
    
    ctx->function_proto = JSI_NewCFunction3(ctx, jsi_function_proto, "", 0,
                                           JSI_CFUNC_generic, 0,
                                           ctx->class_proto[JSI_CLASS_OBJECT]);
    ctx->class_proto[JSI_CLASS_BYTECODE_FUNCTION] = JSI_DupValue(ctx, ctx->function_proto);
    ctx->class_proto[JSI_CLASS_ERROR] = JSI_NewObject(ctx);
#if 0
    /* these are auto-initialized from jsi_error_proto_funcs,
       but delaying might be a problem */
    JSI_DefinePropertyValue(ctx, ctx->class_proto[JSI_CLASS_ERROR], JSI_ATOM_name,
                           JSI_AtomToString(ctx, JSI_ATOM_Error),
                           JSI_PROP_WRITABLE | JSI_PROP_CONFIGURABLE);
    JSI_DefinePropertyValue(ctx, ctx->class_proto[JSI_CLASS_ERROR], JSI_ATOM_message,
                           JSI_AtomToString(ctx, JSI_ATOM_empty_string),
                           JSI_PROP_WRITABLE | JSI_PROP_CONFIGURABLE);
#endif
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_ERROR],
                               jsi_error_proto_funcs,
                               countof(jsi_error_proto_funcs));

    for(i = 0; i < JSI_NATIVE_ERROR_COUNT; i++) {
        proto = JSI_NewObjectProto(ctx, ctx->class_proto[JSI_CLASS_ERROR]);
        JSI_DefinePropertyValue(ctx, proto, JSI_ATOM_name,
                               JSI_NewAtomString(ctx, native_error_name[i]),
                               JSI_PROP_WRITABLE | JSI_PROP_CONFIGURABLE);
        JSI_DefinePropertyValue(ctx, proto, JSI_ATOM_message,
                               JSI_AtomToString(ctx, JSI_ATOM_empty_string),
                               JSI_PROP_WRITABLE | JSI_PROP_CONFIGURABLE);
        ctx->native_error_proto[i] = proto;
    }

    /* the array prototype is an array */
    ctx->class_proto[JSI_CLASS_ARRAY] =
        JSI_NewObjectProtoClass(ctx, ctx->class_proto[JSI_CLASS_OBJECT],
                               JSI_CLASS_ARRAY);

    ctx->array_shape = jsi_new_shape2(ctx, get_proto_obj(ctx->class_proto[JSI_CLASS_ARRAY]),
                                     JSI_PROP_INITIAL_HASH_SIZE, 1);
    add_shape_property(ctx, &ctx->array_shape, NULL,
                       JSI_ATOM_length, JSI_PROP_WRITABLE | JSI_PROP_LENGTH);

    /* XXX: could test it on first context creation to ensure that no
       new atoms are created in JSI_AddIntrinsicBasicObjects(). It is
       necessary to avoid useless renumbering of atoms after
       JSI_EvalBinary() if it is done just after
       JSI_AddIntrinsicBasicObjects(). */
    //    assert(ctx->rt->atom_count == JSI_ATOM_END);
}

void JSI_AddIntrinsicBaseObjects(JSIContext *ctx)
{
    int i;
    JSIValueConst obj, number_obj;
    JSIValue obj1;

    ctx->throw_type_error = JSI_NewCFunction(ctx, jsi_throw_type_error, NULL, 0);

    /* add caller and arguments properties to throw a TypeError */
    JSI_DefineProperty(ctx, ctx->function_proto, JSI_ATOM_caller, JSI_UNDEFINED,
                      ctx->throw_type_error, ctx->throw_type_error,
                      JSI_PROP_HAS_GET | JSI_PROP_HAS_SET |
                      JSI_PROP_HAS_CONFIGURABLE | JSI_PROP_CONFIGURABLE);
    JSI_DefineProperty(ctx, ctx->function_proto, JSI_ATOM_arguments, JSI_UNDEFINED,
                      ctx->throw_type_error, ctx->throw_type_error,
                      JSI_PROP_HAS_GET | JSI_PROP_HAS_SET |
                      JSI_PROP_HAS_CONFIGURABLE | JSI_PROP_CONFIGURABLE);
    JSI_FreeValue(ctx, jsi_object_seal(ctx, JSI_UNDEFINED, 1, (JSIValueConst *)&ctx->throw_type_error, 1));

    ctx->global_obj = JSI_NewObject(ctx);
    ctx->global_var_obj = JSI_NewObjectProto(ctx, JSI_NULL);

    /* Object */
    obj = JSI_NewGlobalCConstructor(ctx, "Object", jsi_object_constructor, 1,
                                   ctx->class_proto[JSI_CLASS_OBJECT]);
    JSI_SetPropertyFunctionList(ctx, obj, jsi_object_funcs, countof(jsi_object_funcs));
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_OBJECT],
                               jsi_object_proto_funcs, countof(jsi_object_proto_funcs));

    /* Function */

    /* Error */
    obj1 = JSI_NewCFunctionMagic(ctx, jsi_error_constructor,
                                "Error", 1, JSI_CFUNC_constructor_or_func_magic, -1);
    JSI_NewGlobalCConstructor2(ctx, obj1,
                              "Error", ctx->class_proto[JSI_CLASS_ERROR]);
    JSI_SetPropertyFunctionList(ctx, obj1, jsi_error_funcs, countof(jsi_error_funcs));

    /* Used to squelch a -Wcast-function-type warning. */
    JSICFunctionType ft = { .generic_magic = jsi_error_constructor };
    for(i = 0; i < JSI_NATIVE_ERROR_COUNT; i++) {
        JSIValue func_obj;
        int n_args;
        n_args = 1 + (i == JSI_AGGREGATE_ERROR);
        func_obj = JSI_NewCFunction3(ctx, ft.generic,
                                    native_error_name[i], n_args,
                                    JSI_CFUNC_constructor_or_func_magic, i, obj1);
        JSI_NewGlobalCConstructor2(ctx, func_obj, native_error_name[i],
                                  ctx->native_error_proto[i]);
    }

    /* Iterator prototype */
    ctx->iterator_proto = JSI_NewObject(ctx);
    JSI_SetPropertyFunctionList(ctx, ctx->iterator_proto,
                               jsi_iterator_proto_funcs,
                               countof(jsi_iterator_proto_funcs));

    /* Array */
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_ARRAY],
                               jsi_array_proto_funcs,
                               countof(jsi_array_proto_funcs));

    obj = JSI_NewGlobalCConstructor(ctx, "Array", jsi_array_constructor, 1,
                                   ctx->class_proto[JSI_CLASS_ARRAY]);
    ctx->array_ctor = JSI_DupValue(ctx, obj);
    JSI_SetPropertyFunctionList(ctx, obj, jsi_array_funcs,
                               countof(jsi_array_funcs));

    /* XXX: create auto_initializer */
    {
        /* initialize Array.prototype[Symbol.unscopables] */
        static const char unscopables[] =
            "at" "\0"
            "copyWithin" "\0"
            "entries" "\0"
            "fill" "\0"
            "find" "\0"
            "findIndex" "\0"
            "findLast" "\0"
            "findLastIndex" "\0"
            "flat" "\0"
            "flatMap" "\0"
            "includes" "\0"
            "keys" "\0"
            "toReversed" "\0"
            "toSorted" "\0"
            "toSpliced" "\0"
            "values" "\0";
        const char *p = unscopables;
        obj1 = JSI_NewObjectProto(ctx, JSI_NULL);
        for(p = unscopables; *p; p += strlen(p) + 1) {
            JSI_DefinePropertyValueStr(ctx, obj1, p, JSI_TRUE, JSI_PROP_C_W_E);
        }
        JSI_DefinePropertyValue(ctx, ctx->class_proto[JSI_CLASS_ARRAY],
                               JSI_ATOM_Symbol_unscopables, obj1,
                               JSI_PROP_CONFIGURABLE);
    }

    /* needed to initialize arguments[Symbol.iterator] */
    ctx->array_proto_values =
        JSI_GetProperty(ctx, ctx->class_proto[JSI_CLASS_ARRAY], JSI_ATOM_values);

    ctx->class_proto[JSI_CLASS_ARRAY_ITERATOR] = JSI_NewObjectProto(ctx, ctx->iterator_proto);
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_ARRAY_ITERATOR],
                               jsi_array_iterator_proto_funcs,
                               countof(jsi_array_iterator_proto_funcs));

    /* parseFloat and parseInteger must be defined before Number
       because of the Number.parseFloat and Number.parseInteger
       aliases */
    JSI_SetPropertyFunctionList(ctx, ctx->global_obj, jsi_global_funcs,
                               countof(jsi_global_funcs));

    /* Number */
    ctx->class_proto[JSI_CLASS_NUMBER] = JSI_NewObjectProtoClass(ctx, ctx->class_proto[JSI_CLASS_OBJECT],
                                                               JSI_CLASS_NUMBER);
    JSI_SetObjectData(ctx, ctx->class_proto[JSI_CLASS_NUMBER], JSI_NewInt32(ctx, 0));
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_NUMBER],
                               jsi_number_proto_funcs,
                               countof(jsi_number_proto_funcs));
    number_obj = JSI_NewGlobalCConstructor(ctx, "Number", jsi_number_constructor, 1,
                                          ctx->class_proto[JSI_CLASS_NUMBER]);
    JSI_SetPropertyFunctionList(ctx, number_obj, jsi_number_funcs, countof(jsi_number_funcs));

    /* Boolean */
    ctx->class_proto[JSI_CLASS_BOOLEAN] = JSI_NewObjectProtoClass(ctx, ctx->class_proto[JSI_CLASS_OBJECT],
                                                                JSI_CLASS_BOOLEAN);
    JSI_SetObjectData(ctx, ctx->class_proto[JSI_CLASS_BOOLEAN], JSI_NewBool(ctx, FALSE));
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_BOOLEAN], jsi_boolean_proto_funcs,
                               countof(jsi_boolean_proto_funcs));
    JSI_NewGlobalCConstructor(ctx, "Boolean", jsi_boolean_constructor, 1,
                             ctx->class_proto[JSI_CLASS_BOOLEAN]);

    /* String */
    ctx->class_proto[JSI_CLASS_STRING] = JSI_NewObjectProtoClass(ctx, ctx->class_proto[JSI_CLASS_OBJECT],
                                                               JSI_CLASS_STRING);
    JSI_SetObjectData(ctx, ctx->class_proto[JSI_CLASS_STRING], JSI_AtomToString(ctx, JSI_ATOM_empty_string));
    obj = JSI_NewGlobalCConstructor(ctx, "String", jsi_string_constructor, 1,
                                   ctx->class_proto[JSI_CLASS_STRING]);
    JSI_SetPropertyFunctionList(ctx, obj, jsi_string_funcs,
                               countof(jsi_string_funcs));
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_STRING], jsi_string_proto_funcs,
                               countof(jsi_string_proto_funcs));

    ctx->class_proto[JSI_CLASS_STRING_ITERATOR] = JSI_NewObjectProto(ctx, ctx->iterator_proto);
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_STRING_ITERATOR],
                               jsi_string_iterator_proto_funcs,
                               countof(jsi_string_iterator_proto_funcs));

    /* Math: create as autoinit object */

    /* ES6 Reflect: create as autoinit object */

    /* ES6 Symbol */
    ctx->class_proto[JSI_CLASS_SYMBOL] = JSI_NewObject(ctx);
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_SYMBOL], jsi_symbol_proto_funcs,
                               countof(jsi_symbol_proto_funcs));
    obj = JSI_NewGlobalCConstructor(ctx, "Symbol", jsi_symbol_constructor, 0,
                                   ctx->class_proto[JSI_CLASS_SYMBOL]);
    JSI_SetPropertyFunctionList(ctx, obj, jsi_symbol_funcs,
                               countof(jsi_symbol_funcs));
    for(i = JSI_ATOM_Symbol_toPrimitive; i < JSI_ATOM_END; i++) {
        char buf[ATOM_GET_STR_BUF_SIZE];
        const char *str, *p;
        str = JSI_AtomGetStr(ctx, buf, sizeof(buf), i);
        /* skip "Symbol." */
        p = strchr(str, '.');
        if (p)
            str = p + 1;
        JSI_DefinePropertyValueStr(ctx, obj, str, JSI_AtomToValue(ctx, i), 0);
    }

    /* ES6 Generator */
    ctx->class_proto[JSI_CLASS_GENERATOR] = JSI_NewObjectProto(ctx, ctx->iterator_proto);
    JSI_SetPropertyFunctionList(ctx, ctx->class_proto[JSI_CLASS_GENERATOR],
                               jsi_generator_proto_funcs,
                               countof(jsi_generator_proto_funcs));

    ctx->class_proto[JSI_CLASS_GENERATOR_FUNCTION] = JSI_NewObjectProto(ctx, ctx->function_proto);
    obj1 = JSI_NewCFunction3(ctx, (JSICFunction *)jsi_function_constructor,
                            "GeneratorFunction", 1,
                            JSI_CFUNC_constructor_or_func_magic, JSI_FUNC_GENERATOR,
                            ctx->function_ctor);
    JSI_SetPropertyFunctionList(ctx,
                               ctx->class_proto[JSI_CLASS_GENERATOR_FUNCTION],
                               jsi_generator_function_proto_funcs,
                               countof(jsi_generator_function_proto_funcs));
    JSI_SetConstructor2(ctx, ctx->class_proto[JSI_CLASS_GENERATOR_FUNCTION],
                       ctx->class_proto[JSI_CLASS_GENERATOR],
                       JSI_PROP_CONFIGURABLE, JSI_PROP_CONFIGURABLE);
    JSI_SetConstructor2(ctx, obj1, ctx->class_proto[JSI_CLASS_GENERATOR_FUNCTION],
                       0, JSI_PROP_CONFIGURABLE);
    JSI_FreeValue(ctx, obj1);

    /* global properties */
    // ctx->eval_obj = JSI_NewCFunction(ctx, jsi_global_eval, "eval", 1);
    JSI_DefinePropertyValue(ctx, ctx->global_obj, JSI_ATOM_eval,
                           JSI_DupValue(ctx, ctx->eval_obj),
                           JSI_PROP_WRITABLE | JSI_PROP_CONFIGURABLE);

    JSI_DefinePropertyValue(ctx, ctx->global_obj, JSI_ATOM_globalThis,
                           JSI_DupValue(ctx, ctx->global_obj),
                           JSI_PROP_CONFIGURABLE | JSI_PROP_WRITABLE);

    /* BigInt */
}

/* Typed Arrays */









#define special_indexOf 0
#define special_lastIndexOf 1
#define special_includes -1







